/* RedRoom Fitness — Global Styles */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Oswald:wght@400;500;600;700&display=swap');

:root {
  --red: oklch(50% 0.22 25);
  --red-dark: oklch(40% 0.18 25);
  --black: oklch(8% 0.01 265);
  --black-deep: oklch(5% 0.005 265);
  --white: oklch(98% 0.01 265);
  --gray: oklch(65% 0.02 265);
  --gray-dark: oklch(30% 0.015 265);
  --gray-mid: oklch(45% 0.015 265);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { font-size: 16px; scroll-behavior: smooth; }

body {
  font-family: 'Inter', Helvetica Neue, sans-serif;
  background: var(--black);
  color: var(--white);
  line-height: 1.6;
  overflow-x: hidden;
}

h1, h2, h3, h4, h5, h6 {
  font-family: 'Oswald', 'Bebas Neue', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-weight: 600;
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }

/* === NAVIGATION === */
.top-bar {
  background: var(--red);
  color: var(--white);
  padding: 0.5rem 1rem;
  text-align: center;
  font-size: 0.85rem;
  font-weight: 500;
  letter-spacing: 0.05em;
}
.top-bar a { color: var(--white); text-decoration: underline; font-weight: 700; }

.navbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 2rem;
  background: var(--black-deep);
  border-bottom: 1px solid var(--gray-dark);
  position: sticky;
  top: 0;
  z-index: 1000;
}
.logo { font-family: 'Oswald', sans-serif; font-size: 1.8rem; font-weight: 700; color: var(--red); text-transform: uppercase; }
.logo span { color: var(--white); }

.nav-links { display: flex; gap: 2rem; list-style: none; }
.nav-links a {
  font-family: 'Oswald', sans-serif;
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gray);
  transition: color 0.3s;
}
.nav-links a:hover, .nav-links a.active { color: var(--red); }

.nav-cta { display: flex; gap: 1rem; }
.btn {
  font-family: 'Oswald', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  padding: 0.75rem 1.5rem;
  border-radius: 2px;
  font-weight: 600;
  transition: all 0.3s;
  display: inline-block;
  text-align: center;
}
.btn-primary {
  background: var(--red);
  color: var(--white);
}
.btn-primary:hover { background: var(--red-dark); transform: translateY(-2px); }
.btn-outline {
  border: 2px solid var(--red);
  color: var(--red);
  background: transparent;
}
.btn-outline:hover { background: var(--red); color: var(--white); }
.btn-large { padding: 1rem 2.5rem; font-size: 1.1rem; }

/* Mobile Menu */
.hamburger { display: none; flex-direction: column; gap: 5px; cursor: pointer; }
.hamburger span { width: 25px; height: 2px; background: var(--white); }

/* === HERO === */
.hero {
  min-height: 90vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 4rem 2rem;
  position: relative;
  background: linear-gradient(135deg, var(--black-deep) 0%, var(--black) 100%);
}
.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, rgba(255,0,0,0.1) 0%, transparent 70%);
}
.hero-content { position: relative; z-index: 1; max-width: 900px; }
.hero h1 {
  font-size: clamp(3rem, 8vw, 6rem);
  line-height: 1;
  margin-bottom: 1.5rem;
  text-shadow: 0 0 60px rgba(255,0,0,0.3);
}
.hero h1 .accent { color: var(--red); }
.hero-subtitle {
  font-size: 1.25rem;
  color: var(--gray);
  margin-bottom: 2.5rem;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}
.hero-ctas { display: flex; gap: 1rem; justify-content: center; flex-wrap: wrap; }

/* === SECTIONS === */
.section { padding: 6rem 2rem; }
.section-dark { background: var(--black-deep); }
.section-heading {
  font-size: clamp(2rem, 4vw, 3rem);
  text-align: center;
  margin-bottom: 1rem;
}
.section-subheading {
  text-align: center;
  color: var(--gray);
  max-width: 600px;
  margin: 0 auto 3rem;
}

/* === COMMUNITY PROMO === */
.community-promo {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
  max-width: 1200px;
  margin: 0 auto;
}
.community-text h2 { font-size: 3rem; margin-bottom: 1.5rem; }
.community-text p { color: var(--gray); font-size: 1.1rem; margin-bottom: 2rem; }
.community-image {
  height: 400px;
  background: linear-gradient(135deg, var(--red) 0%, var(--red-dark) 100%);
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: 'Oswald', sans-serif;
  font-size: 2rem;
  text-transform: uppercase;
  opacity: 0.9;
}

/* === TWO WAYS === */
.two-ways-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  max-width: 1000px;
  margin: 0 auto;
}
.two-ways-card {
  background: var(--black-deep);
  border: 1px solid var(--gray-dark);
  padding: 3rem;
  border-radius: 4px;
  text-align: center;
  transition: all 0.3s;
}
.two-ways-card:hover { border-color: var(--red); transform: translateY(-4px); }
.two-ways-card h3 {
  font-size: 2rem;
  color: var(--red);
  margin-bottom: 1rem;
}
.two-ways-card p { color: var(--gray); }

/* === STUDIO EXPERIENCE === */
.studio-exp {
  text-align: center;
  max-width: 800px;
  margin: 0 auto;
}
.studio-exp h2 { font-size: 3rem; margin-bottom: 1.5rem; }
.studio-exp p { color: var(--gray); font-size: 1.1rem; margin-bottom: 2rem; }

/* === FREE TRIAL CTA === */
.free-trial-cta {
  background: var(--red);
  text-align: center;
  padding: 5rem 2rem;
}
.free-trial-cta h2 { font-size: 3rem; margin-bottom: 1.5rem; }
.free-trial-cta .btn {
  background: var(--white);
  color: var(--red);
  font-size: 1.1rem;
  padding: 1rem 3rem;
}
.free-trial-cta .btn:hover { background: var(--black); color: var(--white); }

/* === CAROUSEL === */
.carousel-section { padding: 4rem 0; overflow: hidden; }
.carousel {
  position: relative;
  max-width: 100%;
  overflow: hidden;
}
.carousel-track {
  display: flex;
  transition: transform 0.5s ease-in-out;
}
.carousel-slide {
  min-width: 100%;
  height: 500px;
  background: linear-gradient(135deg, var(--gray-dark) 0%, var(--black) 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: 'Oswald', sans-serif;
  font-size: 2rem;
  text-transform: uppercase;
  flex-shrink: 0;
}
.carousel-slide:nth-child(1) { background: linear-gradient(135deg, #2a1a1a, var(--black)); }
.carousel-slide:nth-child(2) { background: linear-gradient(135deg, #1a2a1a, var(--black)); }
.carousel-slide:nth-child(3) { background: linear-gradient(135deg, #1a1a2a, var(--black)); }
.carousel-controls {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 100%;
  display: flex;
  justify-content: space-between;
  padding: 0 1rem;
  pointer-events: none;
}
.carousel-btn {
  width: 50px;
  height: 50px;
  border-radius: 50%;
  background: rgba(0,0,0,0.7);
  color: var(--white);
  font-size: 1.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: all;
  cursor: pointer;
  transition: background 0.3s;
}
.carousel-btn:hover { background: var(--red); }
.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 1rem;
}
.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gray-dark);
  cursor: pointer;
  transition: background 0.3s;
}
.carousel-dot.active { background: var(--red); }

/* === NEWSLETTER === */
.newsletter { background: var(--black-deep); padding: 5rem 2rem; text-align: center; }
.newsletter h2 { font-size: 2.5rem; margin-bottom: 1rem; }
.newsletter p { color: var(--gray); margin-bottom: 2rem; }
.newsletter-form {
  display: flex;
  gap: 1rem;
  max-width: 500px;
  margin: 0 auto;
  flex-wrap: wrap;
  justify-content: center;
}
.newsletter-form input {
  flex: 1;
  min-width: 250px;
  padding: 1rem;
  border: 2px solid var(--gray-dark);
  background: var(--black);
  color: var(--white);
  font-size: 1rem;
  border-radius: 2px;
  outline: none;
  transition: border-color 0.3s;
}
.newsletter-form input:focus { border-color: var(--red); }
.newsletter-form input.error { border-color: #ff4444; }
.newsletter-form button { padding: 1rem 2rem; }
.newsletter-message {
  margin-top: 1rem;
  font-size: 0.9rem;
  min-height: 1.5rem;
}
.newsletter-message.success { color: #44ff44; }
.newsletter-message.error { color: #ff4444; }

/* === FOOTER === */
.footer {
  background: var(--black-deep);
  padding: 4rem 2rem 2rem;
  border-top: 1px solid var(--gray-dark);
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 3rem;
  max-width: 1200px;
  margin: 0 auto 3rem;
}
.footer-col h4 {
  font-size: 0.9rem;
  color: var(--red);
  margin-bottom: 1rem;
}
.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 0.5rem; }
.footer-col a { color: var(--gray); font-size: 0.9rem; transition: color 0.3s; }
.footer-col a:hover { color: var(--white); }
.footer-bottom {
  border-top: 1px solid var(--gray-dark);
  padding-top: 2rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
  max-width: 1200px;
  margin: 0 auto;
}
.footer-bottom p { color: var(--gray); font-size: 0.85rem; }
.country-selector { position: relative; display: inline-block; }
.country-selector button {
  background: var(--gray-dark);
  color: var(--white);
  padding: 0.5rem 1rem;
  border-radius: 2px;
  font-size: 0.85rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.country-dropdown {
  position: absolute;
  bottom: 100%;
  right: 0;
  background: var(--black);
  border: 1px solid var(--gray-dark);
  border-radius: 2px;
  min-width: 150px;
  display: none;
  z-index: 100;
}
.country-dropdown.show { display: block; }
.country-dropdown button {
  width: 100%;
  padding: 0.75rem 1rem;
  text-align: left;
  background: none;
  color: var(--gray);
  border-radius: 0;
}
.country-dropdown button:hover { background: var(--gray-dark); color: var(--white); }

/* === WORKOUT PAGE === */
.method-overview { max-width: 800px; margin: 0 auto; text-align: center; }
.method-overview h2 { font-size: 3rem; margin-bottom: 1.5rem; }
.method-overview p { color: var(--gray); font-size: 1.1rem; line-height: 1.8; }

/* === TOGGLE === */
.toggle-container {
  display: flex;
  justify-content: center;
  gap: 0;
  margin: 3rem auto;
  max-width: 400px;
}
.toggle-btn {
  padding: 1rem 2rem;
  font-family: 'Oswald', sans-serif;
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  background: var(--gray-dark);
  color: var(--gray);
  border: 2px solid var(--gray-dark);
  transition: all 0.3s;
}
.toggle-btn:first-child { border-radius: 4px 0 0 4px; }
.toggle-btn:last-child { border-radius: 0 4px 4px 0; }
.toggle-btn.active {
  background: var(--red);
  color: var(--white);
  border-color: var(--red);
}
.toggle-btn:not(.active):hover { background: var(--gray-mid); color: var(--white); }

.toggle-content { display: none; text-align: center; max-width: 700px; margin: 0 auto; }
.toggle-content.active { display: block; }
.toggle-content h3 { font-size: 2rem; margin-bottom: 1rem; color: var(--red); }
.toggle-content p { color: var(--gray); }

/* === SCHEDULE TABLE === */
.schedule-table {
  max-width: 800px;
  margin: 0 auto;
  width: 100%;
  border-collapse: collapse;
}
.schedule-table th, .schedule-table td {
  padding: 1rem;
  text-align: left;
  border-bottom: 1px solid var(--gray-dark);
}
.schedule-table th {
  font-family: 'Oswald', sans-serif;
  text-transform: uppercase;
  color: var(--red);
  font-size: 0.9rem;
  letter-spacing: 0.1em;
}
.schedule-table td { color: var(--gray); }
.schedule-table tr:hover td { background: rgba(255,0,0,0.05); }

/* === INSTRUCTOR GRID === */
.filter-bar {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 3rem;
  flex-wrap: wrap;
}
.filter-btn {
  padding: 0.75rem 1.5rem;
  font-family: 'Oswald', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  background: transparent;
  border: 2px solid var(--gray-dark);
  color: var(--gray);
  border-radius: 2px;
  transition: all 0.3s;
}
.filter-btn.active, .filter-btn:hover {
  background: var(--red);
  border-color: var(--red);
  color: var(--white);
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 2rem;
  max-width: 1200px;
  margin: 0 auto;
}
.instructor-card {
  background: var(--black-deep);
  border: 1px solid var(--gray-dark);
  border-radius: 4px;
  overflow: hidden;
  transition: all 0.3s;
}
.instructor-card:hover { border-color: var(--red); transform: translateY(-4px); }
.instructor-photo {
  height: 250px;
  background: linear-gradient(135deg, var(--gray-dark), var(--black));
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: 'Oswald', sans-serif;
  font-size: 3rem;
  color: var(--red);
}
.instructor-info { padding: 1.5rem; }
.instructor-info h3 { font-size: 1.3rem; margin-bottom: 0.5rem; }
.instructor-info p { color: var(--gray); font-size: 0.9rem; margin-bottom: 1rem; }
.instructor-info a { color: var(--red); font-family: 'Oswald', sans-serif; text-transform: uppercase; letter-spacing: 0.05em; }

/* === FAQ ACCORDION === */
.faq-list { max-width: 800px; margin: 0 auto; }
.faq-item { border-bottom: 1px solid var(--gray-dark); }
.faq-question {
  width: 100%;
  padding: 1.5rem 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: 'Oswald', sans-serif;
  font-size: 1.2rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--white);
  text-align: left;
  cursor: pointer;
  transition: color 0.3s;
}
.faq-question:hover { color: var(--red); }
.faq-question::after {
  content: '+';
  font-size: 1.5rem;
  color: var(--red);
  transition: transform 0.3s;
}
.faq-item.open .faq-question::after { transform: rotate(45deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease-out;
  color: var(--gray);
  line-height: 1.8;
}
.faq-item.open .faq-answer { max-height: 500px; padding-bottom: 1.5rem; }

/* === DIGITAL FEATURES === */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 2rem;
  max-width: 1200px;
  margin: 0 auto;
}
.feature-card {
  background: var(--black-deep);
  border: 1px solid var(--gray-dark);
  padding: 2.5rem;
  border-radius: 4px;
  transition: all 0.3s;
}
.feature-card:hover { border-color: var(--red); }
.feature-card h3 {
  font-size: 1.5rem;
  color: var(--red);
  margin-bottom: 1rem;
}
.feature-card p { color: var(--gray); }

/* === CTA BOOK === */
.cta-book {
  background: var(--red);
  text-align: center;
  padding: 5rem 2rem;
}
.cta-book h2 { font-size: 2.5rem; margin-bottom: 1rem; }
.cta-book p { margin-bottom: 2rem; opacity: 0.9; }

/* === RESPONSIVE === */
@media (max-width: 900px) {
  .community-promo, .two-ways-grid { grid-template-columns: 1fr; }
  .nav-links { display: none; }
  .hamburger { display: flex; }
  .navbar { flex-wrap: wrap; }
  .nav-links.open {
    display: flex;
    flex-direction: column;
    width: 100%;
    padding: 1rem 0;
    gap: 1rem;
  }
}

@media (max-width: 600px) {
  .section { padding: 4rem 1rem; }
  .hero { min-height: 70vh; padding: 2rem 1rem; }
  .hero h1 { font-size: 2.5rem; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .newsletter-form { flex-direction: column; }
  .newsletter-form input, .newsletter-form button { width: 100%; }
  .carousel-slide { height: 300px; }
}

/* Mobile nav overlay */
.nav-links.open {
  display: flex !important;
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  background: var(--black-deep);
  flex-direction: column;
  padding: 1rem 2rem;
  border-bottom: 1px solid var(--gray-dark);
}

