/* === NEWSLETTER === */
.newsletter { background: var(--black-deep); padding: 5rem 2rem; text-align: center; }
.newsletter h2 { font-size: 2.5rem; margin-bottom: 1rem; }
.newsletter p { color: var(--gray); margin-bottom: 2rem; }
.newsletter-form {
  display: flex;
  gap: 1rem;
  max-width: 500px;
  margin: 0 auto;
  flex-wrap: wrap;
  justify-content: center;
}
.newsletter-form input {
  flex: 1;
  min-width: 250px;
  padding: 1rem;
  border: 2px solid var(--gray-dark);
  background: var(--black);
  color: var(--white);
  font-size: 1rem;
  border-radius: 2px;
  outline: none;
  transition: border-color 0.3s;
}
.newsletter-form input:focus { border-color: var(--red); }
.newsletter-form input.error { border-color: #ff4444; }
.newsletter-form button { padding: 1rem 2rem; }
.newsletter-message {
  margin-top: 1rem;
  font-size: 0.9rem;
  min-height: 1.5rem;
}
.newsletter-message.success { color: #44ff44; }
.newsletter-message.error { color: #ff4444; }

/* === FOOTER === */
