.method-overview { max-width: 800px; margin: 0 auto; text-align: center; }
.method-overview h2 { font-size: 3rem; margin-bottom: 1.5rem; }
.method-overview p { color: var(--gray); font-size: 1.1rem; line-height: 1.8; }

/* === TOGGLE === */
.toggle-container {
  display: flex;
  justify-content: center;
  gap: 0;
  margin: 3rem auto;
  max-width: 400px;
}
.toggle-btn {
  padding: 1rem 2rem;
  font-family: 'Oswald', sans-serif;
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  background: var(--gray-dark);
  color: var(--gray);
  border: 2px solid var(--gray-dark);
  transition: all 0.3s;
}
.toggle-btn:first-child { border-radius: 4px 0 0 4px; }
.toggle-btn:last-child { border-radius: 0 4px 4px 0; }
.toggle-btn.active {
  background: var(--red);
  color: var(--white);
  border-color: var(--red);
}
.toggle-btn:not(.active):hover { background: var(--gray-mid); color: var(--white); }

.toggle-content { display: none; text-align: center; max-width: 700px; margin: 0 auto; }
.toggle-content.active { display: block; }
.toggle-content h3 { font-size: 2rem; margin-bottom: 1rem; color: var(--red); }
.toggle-content p { color: var(--gray); }

