.schedule-table th, .schedule-table td {
  padding: 1rem;
  text-align: left;
  border-bottom: 1px solid var(--gray-dark);
}
.schedule-table th {
  font-family: 'Oswald', sans-serif;
  text-transform: uppercase;
  color: var(--red);
  font-size: 0.9rem;
  letter-spacing: 0.1em;
}
.schedule-table td { color: var(--gray); }
.schedule-table tr:hover td { background: rgba(255,0,0,0.05); }

